import {account,mountAccountLink} from './account-client.js';
const $=s=>document.querySelector(s);let doc=null,pdfjs=null,page=1,scale=1,token=0,task=null,serial=0;
async function draw(){if(!doc)return;const n=++serial;if(task){try{task.cancel();await task.promise;}catch{}task=null;}try{const p=await doc.getPage(page);if(n!==serial)return;const base=p.getViewport({scale:1}),fit=Math.min(Math.max(160,$('#book-scroll').clientWidth-28),1000)/base.width,css=p.getViewport({scale:fit*scale}),dpr=Math.min(devicePixelRatio||1,2),v=p.getViewport({scale:fit*scale*dpr}),c=$('#book-canvas');c.width=v.width;c.height=v.height;c.style.width=css.width+'px';c.style.height=css.height+'px';c.hidden=false;task=p.render({canvasContext:c.getContext('2d'),viewport:v});await task.promise;if(n!==serial)return;$('#book-page').textContent=page+' / '+doc.numPages;$('#book-prev').disabled=page===1;$('#book-next').disabled=page===doc.numPages;$('#book-zoom').textContent=scale===1?'适合宽度':Math.round(scale*100)+'%';$('#book-scroll').scrollTo(0,0);}catch(error){if(error?.name!=='RenderingCancelledException'){$('#book-message').textContent='此页暂时无法显示，可打开原文件阅读。';console.error(error);}}}
async function openBook(unit){const n=++token,url='assets/'+unit.toLowerCase()+'.pdf';if(!$('#book-reader').open)$('#book-reader').showModal();$('#book-title').textContent=unit+' · Pure Mathematics '+unit.slice(1);$('#book-original').href=url;$('#book-message').textContent='正在读取教材…';$('#book-canvas').hidden=true;page=1;scale=1;try{pdfjs??=await import('./assets/pdfjs/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('./assets/pdfjs/pdf.worker.mjs',import.meta.url).href;const next=await pdfjs.getDocument({url,isEvalSupported:false}).promise;if(n!==token){next.destroy();return;}doc?.destroy();doc=next;$('#book-message').textContent='';await draw();account.activity('book','books').catch(()=>{});}catch(error){if(n!==token)return;$('#book-message').textContent='内嵌阅读暂未载入，请点击“原文件”打开。';console.error(error);}}
async function init(){try{await account.requireUser();await mountAccountLink();document.addEventListener('click',e=>{const button=e.target.closest('[data-book]');if(button)openBook(button.dataset.book);});$('#book-close').addEventListener('click',()=>$('#book-reader').close());$('#book-prev').addEventListener('click',()=>{if(page>1){page--;draw();}});$('#book-next').addEventListener('click',()=>{if(doc&&page<doc.numPages){page++;draw();}});let x=0,y=0;$('#book-scroll').addEventListener('touchstart',e=>{x=e.changedTouches[0].clientX;y=e.changedTouches[0].clientY;},{passive:true});$('#book-scroll').addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-x,dy=e.changedTouches[0].clientY-y;if(Math.abs(dx)<55||Math.abs(dx)<=Math.abs(dy))return;if(dx<0&&doc&&page<doc.numPages)page++;else if(dx>0&&page>1)page--;else return;draw();},{passive:true});$('#book-plus').addEventListener('click',()=>{scale=Math.min(3,scale+.25);draw();});$('#book-minus').addEventListener('click',()=>{scale=Math.max(.5,scale-.25);draw();});$('#book-full').addEventListener('click',async()=>{const el=$('#book-reader'),on=el.classList.toggle('expanded');$('#book-full').textContent=on?'退出全屏':'全屏阅读';try{if(on&&document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else if(!on&&document.fullscreenElement)await document.exitFullscreen();}catch{}draw();});$('#book-reader').addEventListener('close',()=>{token++;serial++;task?.cancel();$('#book-reader').classList.remove('expanded');$('#book-full').textContent='全屏阅读';if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});});let resize;window.addEventListener('resize',()=>{clearTimeout(resize);resize=setTimeout(()=>{if($('#book-reader').open)draw();},150);});account.activity('visit','books').catch(()=>{});}catch(error){console.error(error);$('.books-main').innerHTML='<div class="empty"><h1>教材暂时无法载入</h1><p>请刷新页面重试。</p></div>';}}
init();
